#!/bin/bash
# In-distribution counterpart to the Terminal-Bench eval: 16 SWE-Gym instances
# the fine-tune never saw, in repos it did, generated by the same
# mini-swe-agent harness and the same effort schedule as the training corpus.
#
# Record once against one drafter, then replay the frozen call set against the
# others -- identical to the Terminal-Bench methodology, so trajectory drift is
# not a confound.
set -x
R=/mnt/data/src/muse-glimmer-dspark
AV=/mnt/data/agentvenv
TD=/mnt/data/traces/swegym-holdout-record
CTR=vllm-swegym-rec
PORT=8051
mkdir -p "$TD" /mnt/data/runs/holdout

# order the subset so each effort level is one contiguous slice
python3 - <<'PY'
import json
p="/mnt/data/bench/swegym_holdout/train.jsonl"
rows=[json.loads(l) for l in open(p)]
order={"low":0,"medium":1,"high":2,"xhigh":3}
rows.sort(key=lambda r:(order[r["reasoning_strength"]], r["instance_id"]))
open(p,"w").write("".join(json.dumps(r)+"\n" for r in rows))
print([ (r["reasoning_strength"], r["instance_id"]) for r in rows ])
PY

sudo docker rm -f "$CTR" >/dev/null 2>&1 || true
sudo docker run -d --name "$CTR" --gpus '"device=0"' --network host --ipc host \
  -v /mnt/data:/mnt/data -e HF_HOME=/mnt/data/hf \
  -e TARGET_MODEL=meta-models/Muse-Glimmer-30B -e SPEC_METHOD=dflash \
  -e SPECULATOR=/mnt/data/speculators/dflash2 \
  -e NUM_SPEC_TOKENS=15 -e PORT=$PORT specd:latest bash "$R/docker/serve_patched.sh" >/dev/null
for i in $(seq 1 200); do
  sudo docker ps --format '{{.Names}}' | grep -qx "$CTR" || { echo "SERVER DIED"; sudo docker logs "$CTR" 2>&1|tail -30; exit 1; }
  curl -sf "http://127.0.0.1:$PORT/v1/models" >/dev/null 2>&1 && break; sleep 10
done
curl -sf "http://127.0.0.1:$PORT/v1/models" >/dev/null || { echo TIMEOUT; exit 1; }

UPSTREAM_URL="http://127.0.0.1:$PORT/v1/chat/completions" TRACE_DIR="$TD" PORT=8080 \
  setsid nohup python3 "$R/scripts/proxy.py" > /mnt/data/logs/holdout_proxy.log 2>&1 < /dev/null &
sleep 5
curl -sf http://127.0.0.1:8080/v1/chat/completions -X POST -H 'content-type: application/json' \
  -d '{"model":"meta-models/Muse-Glimmer-30B","messages":[{"role":"user","content":"hi"}],"max_tokens":4}' | head -c 200
echo

cd "$R"
export MSWEA_CONFIGURED=true
chmod u+w /mnt/data/bench/swegym_holdout/train.jsonl 2>/dev/null || true
i=0
for eff in low medium high xhigh; do
  lo=$i; hi=$((i+4)); i=$hi
  "$AV/bin/mini-extra" swebench \
    --subset /mnt/data/bench/swegym_holdout --split train --slice "$lo:$hi" \
    -c swebench.yaml -c configs/swegym.yaml -c "configs/effort_${eff}.yaml" \
    -w 4 -o /mnt/data/runs/holdout || echo "slice $lo:$hi returned $?"
done

pkill -f "scripts/proxy.py" || true
sudo docker rm -f "$CTR" >/dev/null 2>&1 || true

# convert the proxy log into replay.py's input schema
python3 - <<'PY'
import json
src="/mnt/data/traces/swegym-holdout-record/calls.jsonl"
out="/mnt/data/eval/swegym_holdout_calls.jsonl"
n=0; bad=0
with open(out,"w") as f:
    for line in open(src):
        d=json.loads(line)
        req=d["request"]; resp=d.get("response") or {}
        st=((req.get("chat_template_kwargs") or {}).get("reasoning_strength"))
        err="error" in resp
        if err: bad+=1
        f.write(json.dumps({"id":d["traj"],"ts":d["ts"],"is_error":err,
                            "reasoning_strength":st,"request":req,
                            "prompt_tokens":(resp.get("usage") or {}).get("prompt_tokens"),
                            "completion_tokens":(resp.get("usage") or {}).get("completion_tokens")})+"\n")
        n+=1
print("calls",n,"errors",bad,"->",out)
from collections import Counter
print(Counter(json.loads(l)["reasoning_strength"] for l in open(out)))
PY
echo "=== HOLDOUT RECORDING COMPLETE ==="
